    ['Một vật chuyển động có vận tốc biến đổi một lượng vectơ Δv trong thời gian Δt. Biểu thức tính gia tốc của vật là', ['vectơ a = vectơ Δv · Δt', 'a = vectơ Δv · Δt', 'a = vectơ Δv/Δt', 'vectơ a = vectơ Δv/Δt'], 3, 'Gia tốc là đại lượng vectơ: vectơ a = vectơ Δv/Δt.'],
    [`Một vật chuyển động có đồ thị vận tốc – thời gian như hình bên. Vật chuyển động thẳng ${dh1004GraphV}`, ['Chậm dần đều theo chiều dương.', 'Nhanh dần đều theo chiều âm.', 'Chậm dần đều theo chiều âm.', 'Nhanh dần đều theo chiều dương.'], 0, 'v dương và giảm tuyến tính đến 0 nên vật chậm dần đều theo chiều dương.'],
    ['Mục tiêu của việc học tập môn Vật lí không phải là điều nào sau đây?', ['Nhận biết được năng lực, sở trường của bản thân, định hướng nghề nghiệp.', 'Vận dụng kiến thức, kĩ năng đã học để giải quyết vấn đề trong học tập và cuộc sống.', 'Giải thích nguồn gốc phát sinh và sự tiến hóa của các loài sinh vật.', 'Có được những kiến thức, kĩ năng cơ bản về vật lí.'], 2, 'Nguồn gốc và tiến hóa các loài là nội dung của Sinh học, không phải mục tiêu riêng của Vật lí.'],
    ['Đại lượng nào sau đây là đại lượng vectơ?', ['Tốc độ trung bình.', 'Quãng đường.', 'Thời gian chuyển động.', 'Độ dịch chuyển.'], 3, 'Độ dịch chuyển có độ lớn và hướng nên là đại lượng vectơ.'],
    ['Khi nói về vai trò của vật lí đối với khoa học kĩ thuật và công nghệ, điều nào sau đây không đúng?', ['Vật lí là cơ sở của công nghệ.', 'Vật lí đóng vai trò rất quan trọng trong 4 cuộc cách mạng công nghiệp của thế giới.', 'Vật lí được coi là cơ sở của khoa học tự nhiên.', 'Việc ứng dụng các thành tựu của vật lí vào công nghệ, cuộc sống chỉ đem lại lợi ích cho nhân loại.'], 3, 'Ứng dụng vật lí còn có thể gây tác động tiêu cực nếu sử dụng không an toàn hoặc sai mục đích.']
